(114948,13809,'_wp_attachment_metadata','a:6:{s:5:\"width\";i:960;s:6:\"height\";i:909;s:4:\"file\";s:102:\"2024/01/kinder-mit-erzieherin-spielen-im-sandkasten-auf-dem-spielplatz-vor-dem-gebaeude-des-wf-kin.jpg\";s:8:\"filesize\";i:311974;s:5:\"sizes\";a:3:{s:6:\"medium\";a:5:{s:4:\"file\";s:102:\"kinder-mit-erzieherin-spielen-im-sandkasten-auf-dem-spielplatz-vor-dem-gebaeude-des-wf-kin-300x284.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:284;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:28646;}s:9:\"thumbnail\";a:5:{s:4:\"file\";s:102:\"kinder-mit-erzieherin-spielen-im-sandkasten-auf-dem-spielplatz-vor-dem-gebaeude-des-wf-kin-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:9535;}s:12:\"medium_large\";a:5:{s:4:\"file\";s:102:\"kinder-mit-erzieherin-spielen-im-sandkasten-auf-dem-spielplatz-vor-dem-gebaeude-des-wf-kin-768x727.jpg\";s:5:\"width\";i:768;s:6:\"height\";i:727;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:133971;}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:12:\"Kurt Schwarz\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:850:\"Kinder mit Erzieherin spielen im Sandkasten auf dem Spielplatz vor dem Gebäude eines WF Kindergartens, Foto © Kurt Schwarz, 1980er Jahre. \r\n\r\nDas Werk für Fernsehelektronik (WF) in Berlin Oberschöneweide war der größte „Volkseigene Betrieb“ (VEB) Ost-Berlins und führende Standort für Fernseh- und Elektrotechnik aller Art in der DDR. Dazu zählten unter anderem Elektronenröhren, Messgeräte, Optoelektronik, Halbleitertechnik und nicht zuletzt Bildröhren, die in der DDR ausschließlich hier produziert wurden. Das Werk existierte von 1945 bis 1993, bevor es von Samsung übernommen und dann 2005 endgültig geschlossen wurde.\r\n\r\nKurt Schwarz fotografierte in den 1970er und 1980er Jahren wiederholt freiberuflich für das WF, sowohl für die Betriebszeitung \"WF Sender\" als auch für verschiedene Marketing- und Dokumentationszwecke.\";s:17:\"created_timestamp\";s:10:\"1579958641\";s:9:\"copyright\";s:91:\"© Kurt Schwarz ; Licence: CC BY-NC-SA (https://creativecommons.org/licenses/by-nc-sa/4.0/)\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:64:\"Kinder mit Erzieherin spielen im Sandkasten auf dem Spielplatz v\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:1:{i:0;s:64:\"Kind, Industrie, Mädchen, DDR-Elektroindustrie, Junge, Elektrot\";}}}'),
