(114961,13812,'_wp_attachment_metadata','a:6:{s:5:\"width\";i:960;s:6:\"height\";i:640;s:4:\"file\";s:72:\"2024/01/kinder-im-planschbecken-juni-1977-sw-foto-kurt-schwarz-95017.jpg\";s:8:\"filesize\";i:247736;s:5:\"sizes\";a:3:{s:6:\"medium\";a:5:{s:4:\"file\";s:72:\"kinder-im-planschbecken-juni-1977-sw-foto-kurt-schwarz-95017-300x200.jpg\";s:5:\"width\";i:300;s:6:\"height\";i:200;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:21594;}s:9:\"thumbnail\";a:5:{s:4:\"file\";s:72:\"kinder-im-planschbecken-juni-1977-sw-foto-kurt-schwarz-95017-150x150.jpg\";s:5:\"width\";i:150;s:6:\"height\";i:150;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:9061;}s:12:\"medium_large\";a:5:{s:4:\"file\";s:72:\"kinder-im-planschbecken-juni-1977-sw-foto-kurt-schwarz-95017-768x512.jpg\";s:5:\"width\";i:768;s:6:\"height\";i:512;s:9:\"mime-type\";s:10:\"image/jpeg\";s:8:\"filesize\";i:114922;}}s:10:\"image_meta\";a:12:{s:8:\"aperture\";s:1:\"0\";s:6:\"credit\";s:12:\"Kurt Schwarz\";s:6:\"camera\";s:0:\"\";s:7:\"caption\";s:1082:\"Kinder im Planschbecken. Das Foto wurde im WF-Sender Nr. 22/1977 (4. Juniausgabe) als Aufmacherbild auf der Titelseite veröffentlicht mit der Bildunterschrift: \"Gäste aus Moskau besuchten unsere Sozialeinrichtungen. Unser Bild: Die Hitze lud unsere Jüngsten zum kühlenden Bad im Planschbecken unseres Kindergartens ein. Foto: Schwarz\". Foto © Kurt Schwarz, Juni 1977.\r\n\r\nDas Werk für Fernsehelektronik (WF) in Berlin Oberschöneweide war der größte „Volkseigene Betrieb“ (VEB) Ost-Berlins und führende Standort für Fernseh- und Elektrotechnik aller Art in der DDR. Dazu zählten unter anderem Elektronenröhren, Messgeräte, Optoelektronik, Halbleitertechnik und nicht zuletzt Bildröhren, die in der DDR ausschließlich hier produziert wurden. Das Werk existierte von 1945 bis 1993, bevor es von Samsung übernommen und dann 2005 endgültig geschlossen wurde.\r\n\r\nKurt Schwarz fotografierte in den 1970er und 1980er Jahren wiederholt freiberuflich für das WF, sowohl für die Betriebszeitung \"WF Sender\" als auch für verschiedene Marketing- und Dokumentationszwecke.\";s:17:\"created_timestamp\";s:10:\"1579606838\";s:9:\"copyright\";s:91:\"© Kurt Schwarz ; Licence: CC BY-NC-SA (https://creativecommons.org/licenses/by-nc-sa/4.0/)\";s:12:\"focal_length\";s:1:\"0\";s:3:\"iso\";s:1:\"0\";s:13:\"shutter_speed\";s:1:\"0\";s:5:\"title\";s:59:\"Kinder im Planschbecken, Juni 1977, SW-Foto © Kurt Schwarz\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:1:{i:0;s:64:\"Kind, Freizeit, Baden (Tätigkeit), DDR-Elektroindustrie, Sommer\";}}}'),
