-- Kinder im WF salvage after-state, 2026-06-07.
-- Apply after Archivset schema exists; then run archive and graph sync/verify commands.
-- Row-only artifact: no table DDL. Stationizes the Ausstellung body and keeps legacy chapters private as source refs.
DELETE FROM wp_postmeta WHERE post_id = 17980 AND meta_key IN ('iss_archive_term_slug','iss_exhibition_source','iss_exhibition_type','_iss_legacy_archive_term_slug','_iss_stationized_at_gmt');
SET @kinder_set_id := (SELECT id FROM wp_iss_archive_sets WHERE set_key = 'manual:kinder-im-wf-bildauswahl' LIMIT 1);
DELETE FROM wp_iss_archive_set_members WHERE set_id = @kinder_set_id;
DELETE FROM wp_iss_archive_set_links WHERE set_id = @kinder_set_id OR (post_id = 17980 AND link_role = 'archive_material');
DELETE FROM wp_iss_archive_sets WHERE set_key = 'manual:kinder-im-wf-bildauswahl';
